185	// The observable each corner lesson rests on, from one mean field.
186	function observe(p, r) {
187	  const P = CORNER[p];
188	  if (p === "w196-wheel") {   // the slow band on the station line nearest the tyre's outer shoulder: its edges and width
189	    const ys = [], sp = [];
190	    for (let y = 2; y < 1700; y += 4) { const v = r.vel(P.station, y, P.plane); if (v) { ys.push(y); sp.push(Math.hypot(...v)); } }
191	    const bands = []; let start = null, last = null;
192	    ys.forEach((y, n) => {
193	      if (sp[n] >= P.below) return;
194	      if (start == null || y !== last + 4) { if (start != null) bands.push([start, last]); start = y; }
195	      last = y;
196	    });
197	    if (start != null) bands.push([start, last]);
198	    const dist = b => (P.shoulder < b[0] ? b[0] - P.shoulder : P.shoulder > b[1] ? P.shoulder - b[1] : 0);
199	    const b = bands.sort((u, v) => dist(u) - dist(v))[0] ?? [NaN, NaN];
200	    return { inner: b[0], outer: b[1], width: b[1] - b[0] };
201	  }
202	  const l = trace(r, [1500, P.follow, P.plane], { dt: 8, every: 1, plane: "z", stop: { x: [P.station, 1e9] } }), end = l.at(-1);
203	  return { y: end[0] <= P.station + 20 ? end[1] : NaN, shift: end[0] <= P.station + 20 ? end[1] - P.follow : NaN };
204	}
