26	export function createTunnel({ nx, nz, solid, U = 0.1, nu = 0.0015, smag = 0.16 }) {
27	  const N = nx * nz, tau0 = 3 * nu + 0.5, C = 18 * Math.SQRT2 * smag * smag, uu = 1.5 * U * U;
