52	      const tau = 0.5 * (tau0 + Math.sqrt(tau0 * tau0 + C * Math.sqrt(pxx * pxx + pzz * pzz + 2 * pxz * pxz) / r)), om = 1 / tau;
53	      for (let k = 0; k < 9; k++) {
