  const out={};
  for(const i of [0,3,25,50,100,200,300,518,519]) {
    const ps=[],us=[],gaps=[]; 
    for(let j=0;j<m.nz;j++){let k=j*m.nx+i;if(solid[k])continue;ps.push((rho[k]-1)/(1.5*m.U**2));us.push(u[k]/m.U);if(j*m.h<120)gaps.push(u[k]/m.U);}
